<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class SupportTicket extends Model { protected $table='support_tickets'; protected $guarded=['id']; protected $casts=['last_reply_at'=>'datetime','closed_at'=>'datetime']; public function user(){return $this->belongsTo(User::class);} public function category(){return $this->belongsTo(SupportCategory::class,'category_id');} public function account(){return $this->belongsTo(Accounts::class,'account_id');} public function order(){return $this->belongsTo(StoreOrder::class,'order_id');} public function messages(){return $this->hasMany(SupportMessage::class,'ticket_id');} public function attachments(){return $this->hasMany(SupportAttachment::class,'ticket_id');} public function scopeVisibleTo($q, User $user){return in_array($user->role,['admin','manager'],true)?$q:$q->where('user_id',$user->id);} public function getStatusLabelAttribute(){return ['new'=>'ثبت شده','in_progress'=>'در حال بررسی','waiting_customer'=>'منتظر پاسخ مشتری','answered'=>'پاسخ داده شده','resolved'=>'حل شده','closed'=>'بسته شده'][$this->status]??$this->status;} }
